import sys

def extract_pkg(file_path):
    with open(file_path, 'rb') as f:
        content = f.read()

    # Example parsing logic; it extracts everything after the magic number
    # Assuming the magic number is 0x7F followed by 'PKG' and null bytes
    magic = b'\x7FPKG\x00\x00\x00\x01'
    start = content.find(magic) + len(magic)

    if start >= len(magic):
        extracted_data = content[start:]
        with open('/tmp/extracted_data', 'wb') as out:
            out.write(extracted_data)
            print("Data extracted to /tmp/extracted_data")
    else:
        print("Magic number not found.")

if __name__ == "__main__":
    if len(sys.argv) != 2:
        print("Usage: python extract_pkg.py <path_to_pkg_file>")
    else:
        extract_pkg(sys.argv[1])

